function main() {
  const moviesJsPath = path.join(__dirname, "movies.js");
  const code = fs.readFileSync(moviesJsPath, "utf8");
  const fn = new Function(`${code}; return MOVIES_DB;`);
  const existing = fn();

  const seenTitles = new Set(existing.map((m) => m.title.toLowerCase()));
  const merged = existing.map((m) => ({ ...m, isTarget: true }));

  let added = 0;
  for (const row of ADDITIONAL_MOVIES) {
    const [title, year, composers, genres, source, actors, director, tagline] = row;
    const cleanTitle = title
      .replace(/^TheHunt/, "The Hunt")
      .replace(/^TheLast/, "The Last")
      .replace(/^TheEnglish/, "The English")
      .trim();
    const key = cleanTitle.toLowerCase();
    if (seenTitles.has(key)) continue;

    seenTitles.add(key);
    merged.push({
      id: merged.length + 1,
      title: cleanTitle,
      year,
      composers,
      genres,
      source,
      actors,
      director,
      tagline,
      isTarget: true
    });
    added++;
  }

  merged.forEach((m, i) => {
    m.id = i + 1;
  });

  const output = `// Curated Movie Catalog for CINELE (${merged.length} Iconic Films)
// Factual Film Credits (CC0 / Public Domain Facts — Free for Commercial & Personal Use)

const MOVIES_DB = ${JSON.stringify(merged, null, 2)};
`;

  fs.writeFileSync(moviesJsPath, output, "utf8");
  console.log(`✅ Added ${added} new movies! Total catalog size: ${merged.length} movies.`);
}

main();
